.map{position:relative;border-radius:28px;overflow:hidden;min-height:340px;background:#14141c}.map>svg{position:absolute;inset:0;width:100%;height:100%}
.kpin{position:absolute;left:58%;top:46%;transform:translate(-50%,-100%)}.kpin i{position:absolute;left:50%;bottom:-6px;width:16px;height:16px;margin-left:-8px;border-radius:50%;background:rgba(242,106,27,.5);animation:ring 2.2s infinite}
@keyframes ring{from{transform:scale(.6);opacity:1}to{transform:scale(4);opacity:0}}
.mtag{position:absolute;left:24px;bottom:24px;background:rgba(255,255,255,.95);backdrop-filter:blur(8px);border-radius:18px;padding:14px 18px;box-shadow:0 14px 30px rgba(0,0,0,.2)}.mtag b{display:block;font-size:16px}.mtag small{color:var(--mut);font-size:12.5px}
.lcard{background:#fff;border-radius:28px;padding:32px;border:1px solid rgba(20,20,28,.06);display:flex;flex-direction:column;gap:14px}.lcard h2{font-size:28px;letter-spacing:-.03em}.lcard p{color:var(--mut);line-height:1.7;font-size:15px}
.soc{display:flex;gap:10px;flex-wrap:wrap;margin-top:auto}.soc a{display:inline-flex;align-items:center;gap:8px;padding:10px 15px;border-radius:99px;border:1.5px solid rgba(20,20,28,.1);text-decoration:none;color:var(--ink);font-size:13.5px;font-weight:600;transition:.2s}.soc a:hover{border-color:var(--o);color:var(--o)}
.faq2{margin:90px 0 0;display:grid;grid-template-columns:minmax(0,.8fr) minmax(0,1.2fr);gap:50px}.faq2 h2{font-size:clamp(30px,3.6vw,44px);letter-spacing:-.035em;line-height:1.05;margin:12px 0}
.faq2 details{border-bottom:1px solid rgba(20,20,28,.08)}.faq2 summary{list-style:none;cursor:pointer;padding:20px 40px 20px 0;font-weight:600;font-size:16.5px;position:relative}.faq2 summary::-webkit-details-marker{display:none}
.faq2 summary:after{content:"+";position:absolute;right:4px;top:16px;width:28px;height:28px;border-radius:50%;display:grid;place-items:center;background:#fdf1e8;color:var(--o);font-size:18px;transition:transform .3s}.faq2 details[open] summary:after{transform:rotate(45deg)}
a:focus-visible,button:focus-visible,summary:focus-visible{outline:3px solid rgba(242,106,27,.6);outline-offset:3px;border-radius:10px}
.rv3{opacity:0;transform:translateY(22px);transition:opacity .8s cubic-bezier(.2,.8,.2,1),transform .8s cubic-bezier(.2,.8,.2,1)}.rv3.in{opacity:1;transform:none}
@media(prefers-reduced-motion:reduce){.rv3{opacity:1;transform:none;transition:none}.dot,.kpin i,.okp,.send .klbl,.send .karr{color:#fff;background:none;width:auto;height:auto;border:0;box-shadow:none}.send .ksp{animation:none!important}}
@media(max-width:1060px){.methods{grid-template-columns:repeat(2,minmax(0,1fr))}.cl,.locs,.faq2{grid-template-columns:minmax(0,1fr)}.aside2{position:static;grid-template-columns:repeat(2,minmax(0,1fr))}.faq2{gap:10px}}
@media(max-width:640px){.ch{padding:110px 0 20px}.methods{grid-template-columns:minmax(0,1fr);gap:12px;margin-bottom:44px}.kg2{grid-template-columns:minmax(0,1fr);gap:0}.fc{padding:24px 18px;border-radius:22px}.aside2{grid-template-columns:minmax(0,1fr)}.map{min-height:260px}.locs{margin-top:50px}.faq2{margin-top:60px}.send{width:100%;justify-content:center}.lcard{padding:24px}}
